contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // params: amount to attempt to collect
    function run(uint _am) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (_am)); require(_am <= 1000000000000000000000000000000);
        // ensure this test contract has enough ETH to deposit then collect back
        require(address(this).balance >= _am);

        // Read caller (this contract) balance in c before any action
        uint beforeUserBalance = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint beforeContractBalance = address(c).balance;

        // First deposit _am so that Collect might succeed (this increases on Log as well)
        // must be a top-level state-changing call
        c.Deposit{value: _am}(); if (__ESBMC_reverted()) return;

        // Read balances after deposit and before collect
        uint afterDepositUserBalance = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint afterDepositContractBalance = address(c).balance;

        // Attempt Collect and capture whether it reverted
        bool reverted;
        c.Collect(_am); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // Read balances after collect attempt
        uint finalUserBalance = c.balances(address(this)); if (__ESBMC_reverted()) return;
        uint finalContractBalance = address(c).balance;

        // If Collect did not revert, then the recorded user balance decreased by exactly _am
        // and the contract's Ether balance decreased by exactly _am as well.
        assert(reverted || (afterDepositUserBalance >= _am && afterDepositUserBalance - _am == finalUserBalance && afterDepositContractBalance >= _am && afterDepositContractBalance - _am == finalContractBalance));
    }

    // allow receiving refunds from c
    receive() external payable {}
}

