// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PRIVATE_ETH_CELL} from "../src/PRIVATE_ETH_CELL.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PRIVATE_ETH_CELL c;

    function setUp() public {
        c = new PRIVATE_ETH_CELL();
    }

    function _run(uint256 _am) internal {
        _am = bound(_am, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= _am);
        uint256 beforeUserBalance;
        try c.balances(address(this)) returns (uint256 __r) { beforeUserBalance = __r; } catch { return; }
        uint beforeContractBalance = address(c).balance;
        try c.Deposit{value: _am}() {} catch { return; }
        uint256 afterDepositUserBalance;
        try c.balances(address(this)) returns (uint256 __r) { afterDepositUserBalance = __r; } catch { return; }
        uint afterDepositContractBalance = address(c).balance;
        bool reverted;
        try c.Collect(_am) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint256 finalUserBalance;
        try c.balances(address(this)) returns (uint256 __r) { finalUserBalance = __r; } catch { return; }
        uint finalContractBalance = address(c).balance;
        assertTrue(reverted || (afterDepositUserBalance >= _am && afterDepositUserBalance - _am == finalUserBalance && afterDepositContractBalance >= _am && afterDepositContractBalance - _am == finalContractBalance));
    }

    function testFuzz_run(uint256 _am) public {
        _run(_am);
    }

    receive() external payable {}
}
